const { env } = await import('node:process');
const defStr = env.GRAPH_DEF;
if (!defStr) throw new Error('Missing GRAPH_DEF');
let def;
try { def = JSON.parse(defStr); } catch (e) { throw new Error('Invalid JSON for definition'); }
if (!Array.isArray(def.nodes) || !Array.isArray(def.deps)) throw new Error('Definition must have nodes and deps arrays');
globalThis.graphDef = def;

const { DepGraph } = await import('dependency-graph');
const graph = new DepGraph();
for (const n of globalThis.graphDef.nodes) { graph.addNode(n); }
for (const d of globalThis.graphDef.deps) { graph.addDependency(d.from, d.to); }
globalThis.order = graph.overallOrder();
